//! Issue #228: independent analytic controls, generated by
//! tools/make_pocket_floor_fillets.py from the issue's build123d construction.
use super::common;
use quiddity::features::{self, Context, pockets, slots};
use quiddity::kernel::geom::Surface;

fn read(name: &str) -> quiddity::Part {
    quiddity::read_step_file(&common::fixtures().join(format!("{name}.step"))).unwrap()
}

#[test]
fn closed_floor_rounds_belong_to_a_full_depth_pocket() {
    for (name, corner, uniform, count) in [
        ("pocket_floor_fillet", Some(5.), Some(1.5), 8),
        ("pocket_partial_floor_fillet", None, None, 2),
    ] {
        let part = read(name);
        assert!(part.solid_is_geometrically_valid(0));
        let found = features::recognise(&part);
        assert!(found.failures.is_empty(), "{:?}", found.failures);
        assert_eq!(found.pockets.len(), 1, "{name}: {found:?}");
        assert!(found.slots.is_empty());
        assert!(slots::discover(&Context::new(&part)).is_empty());
        let p = &found.pockets[0];
        assert_eq!((p.width, p.length, p.depth), (20., 30., 4.));
        assert_eq!(p.corner_radius, corner);
        assert_eq!(p.floor_radius, uniform);
        assert_eq!(p.floor_fillets.len(), count);
        let defining = &found.defining["pockets"][0];
        for f in &p.floor_fillets {
            assert_eq!(f.radius, 1.5);
            assert!(defining.contains(&f.face));
            assert!(
                !found.defining["fillets"]
                    .iter()
                    .flatten()
                    .any(|&i| i == f.face)
            );
            assert!(
                !found.defining["blends"]
                    .iter()
                    .flatten()
                    .any(|&i| i == f.face)
            );
            match part.faces[f.face].surface {
                Surface::Cylinder { frame, radius } => {
                    assert_eq!(radius, 1.5);
                    assert!(frame.z[2].abs() < 1e-9, "horizontal floor edge");
                    assert!(matches!(
                        part.faces[f.wall_face].surface,
                        Surface::Plane { .. }
                    ));
                }
                Surface::Torus { minor, .. } => {
                    assert_eq!(minor, 1.5);
                    let Surface::Cylinder { frame, radius } = part.faces[f.wall_face].surface
                    else {
                        panic!("corner support")
                    };
                    assert_eq!(radius, 5.);
                    assert!(frame.z[2].abs() > 1. - 1e-9, "vertical r5 corner");
                }
                _ => panic!("nonanalytic floor transition"),
            }
        }
        let direct = pockets::discover_verified(&Context::new(&part)).unwrap();
        assert_eq!(direct.len(), 1);
        assert_eq!(direct[0].record, *p);
    }
}

#[test]
fn sharp_floor_retains_legacy_families_and_parameters() {
    let part = read("pocket_plain");
    let f = features::recognise(&part);
    assert_eq!(f.pockets.len(), 1);
    assert_eq!(f.blends.len(), 4);
    assert_eq!(f.step_levels.len(), 1); // caller-space; framed publication has two
    let published = quiddity::correspondence::recognise(&part);
    assert_eq!(published.features.step_levels.len(), 2);
    assert_eq!(f.section_recesses.len(), 1);
    assert!(f.slots.is_empty());
    assert!(f.fillets.is_empty());
    let p = &f.pockets[0];
    assert_eq!((p.depth, p.corner_radius), (4., Some(5.)));
    let value = serde_json::to_value(p).unwrap();
    assert!(value.get("floor_radius").is_none());
    assert!(value.get("floor_fillets").is_none());
}

#[test]
fn true_through_slots_do_not_acquire_a_floor() {
    let part = read("golden_straight_and_obround_slots");
    let f = features::recognise(&part);
    assert_eq!(f.slots.len(), 5);
    assert!(f.pockets.is_empty());
    assert!(
        slots::discover(&Context::new(&part))
            .iter()
            .all(|s| s.record.d_hi.raw() - s.record.d_lo.raw() > 0.)
    );
}

#[test]
fn floor_rounds_survive_motion_and_self_contained_publication() {
    let (s, c) = 0.37_f64.sin_cos();
    for name in ["pocket_floor_fillet", "pocket_partial_floor_fillet"] {
        let part = read(name);
        for at in [
            quiddity::kernel::step::IDENTITY,
            [[1., 0., 0., 13.], [0., 0., -1., 27.], [0., 1., 0., -9.]],
            [[c, 0., s, 123.456], [0., 1., 0., -78.9], [-s, 0., c, 41.3]],
        ] {
            let moved = part.transformed(&at).unwrap();
            let recognised = quiddity::correspondence::recognise(&moved);
            let document = quiddity::recognition::document(&recognised, moved.faces.len());
            let records: Vec<_> = document
                .records
                .iter()
                .filter(|r| r.family == "pockets")
                .collect();
            assert_eq!(records.len(), 1, "{name}: {document:?}");
            let p = &records[0].parameters;
            assert_eq!(p["depth"], 4.);
            assert_eq!(
                p["floor_fillets"].as_array().unwrap().len(),
                if name == "pocket_floor_fillet" { 8 } else { 2 }
            );
            assert!(!document.records.iter().any(|r| r.family == "slots"));
            if name == "pocket_floor_fillet" {
                assert_eq!(p["corner_radius"], 5.);
                assert_eq!(p["floor_radius"], 1.5);
            } else {
                assert!(p.get("floor_radius").is_none());
            }
        }
    }
}

#[test]
fn rust_snapshot_pocket_floor_fillets() {
    let actual: serde_json::Map<_, _> = [
        "pocket_plain",
        "pocket_floor_fillet",
        "pocket_partial_floor_fillet",
        "golden_straight_and_obround_slots",
    ]
    .into_iter()
    .map(|name| {
        let part = read(name);
        let r = quiddity::correspondence::recognise(&part);
        let document = quiddity::recognition::document(&r, part.faces.len());
        (
            name.to_owned(),
            serde_json::json!({"recognition": r, "document": document}),
        )
    })
    .collect();
    common::snapshot::check(&common::fixtures(), "pocket_floor_fillets", &actual.into());
}
